#include <stdio.h>
void reverse(int arr[], int n) {
    int i, temp;
    for (i = 0; i < n / 2; i++) {
        temp = arr[i];
        arr[i] = arr[n - 1 - i];
        arr[n - 1 - i] = temp;
    }
}
int main() {
    int arr[] = {1, 2, 3, 4, 5};
    reverse(arr, 5);
    printf("%d %d", arr[0], arr[4]);
    return 0;
}
```

